    def ProsmAns(self):
        query = """
                  SELECT a1.fullname, a1.year, a1.prof, a1.city, o1.data1, o1.num_answer, o1.r_answer from admin1 AS a1 
                  INNER JOIN opros1 AS o1 ON TRIM(o1.user1) = TRIM(a1.login) 
                """

        self.cursor.execute(query)

        self.records = self.cursor.fetchall()

        n14 = 21 		
        n22 = 0			
        l1 = len(list(self.records))
            
        if (self.ProsmMode == 11): 
            name1 = self.line1.text().strip()
            n11 = 1
           
            for i in range(1, l1):
                row11 = self.records[i]
                if (str(row11[0]).strip() == name1):
                    n11 = i + 1	

            if (n11 % 20 == 0):
                page11 = int((n11 - n11 % 20) / 20)			
                n22 = 19
            else: 
                page11 = int((n11 - n11 % 20) / 20) + 1			
                n22 = int(n11 % 20) - 1
			
            self.NumPage = page11  
			
            #print(n22)
            #print(page11)
            #print(n11)
            #print(l1)

            if (self.NumPage * 20 + l1 % 20 > l1):
                n14 = int(l1 % 20 + 1)		            

        else:		
            self.NumPage = 1  
            n22 = 0			
			
        _translate = QtCore.QCoreApplication.translate
        self.label.setText(_translate("MainWindow", "Ответы участников"))
        self.label1.setText(_translate("MainWindow", "  Страница " + str(self.NumPage)))
        self.ProsmMode = 2  

        Shapka2.setShapka2(self.tableWidget, self.ProsmMode)
					
        for i in range(1, n14):
            if (i + 20 * (self.NumPage - 1) - 1 < l1):
                self.row = self.records[i + 20 * (self.NumPage - 1) - 1]
            
                for j in range(0, 7):
                    if self.row[j]:
                        self.tableWidget.setItem(i-1, j, QtWidgets.QTableWidgetItem(str(self.row[j]))) 
                    else:
                        self.tableWidget.setItem(i-1, j, QtWidgets.QTableWidgetItem("")) 

        self.tableWidget.selectRow(n22)
        if (n14 < 21):
            for i in range(n14, 21):
                for j in range(0, 7):
                    self.tableWidget.setItem(i-1, j, QtWidgets.QTableWidgetItem("")) 
		

